changeSet.sql:
UPDATE public.retail_recommendation
SET detail = lo_from_bytea(0, convert_to(detail, 'UTF8'))::text
WHERE detail IS NOT NULL AND detail !~ '^[0-9]+$';

UPDATE public.retail_recommendation
SET explanation = lo_from_bytea(0, convert_to(explanation, 'UTF8'))::text
WHERE explanation IS NOT NULL AND explanation !~ '^[0-9]+$';
